#include <linux/slab.h>
#include <linux/errno.h>
#include <linux/coresight.h>
#include <linux/workqueue.h>

struct trace_event_data {
    struct coresight_device *sink;
    struct work_struct free_work;
    struct path_info **paths;
    int nr_cpus;
};

void *setup_trace_event_data(int event_cpu, void **pages, int nr_pages, bool overwrite)
{
    struct trace_event_data *event_data;
    struct coresight_device *sink;
    struct path_info **paths;
    int cpu;

    event_data = kzalloc(sizeof(*event_data), GFP_KERNEL);
    if (!event_data)
        return NULL;

    sink = coresight_find_device_by_type(CORESIGHT_DEV_TYPE_SINK, 0);
    if (!sink || !sink->alloc_buffer) {
        kfree(event_data);
        return NULL;
    }

    paths = kcalloc(nr_pages, sizeof(struct path_info *), GFP_KERNEL);
    if (!paths) {
        kfree(event_data);
        return NULL;
    }

    for (cpu = 0; cpu < nr_pages; cpu++) {
        paths[cpu] = kzalloc(sizeof(struct path_info), GFP_KERNEL);
        if (!paths[cpu]) {
            int i;
            for (i = 0; i < cpu; i++)
                kfree(paths[i]);
            kfree(paths);
            kfree(event_data);
            return NULL;
        }
        // Initialize path for each CPU
        // (Assuming appropriate fields are available in path_info)
        paths[cpu]->cpu = cpu;
        paths[cpu]->buffer_pages = pages + cpu;
    }

    INIT_WORK(&event_data->free_work, (void (*)(void *))kfree);

    event_data->sink = sink;
    event_data->paths = paths;
    event_data->nr_cpus = nr_pages;

    return event_data;
}

#include <linux/coresight.h>
#include <linux/workqueue.h>
#include <linux/slab.h>
#include <linux/mm.h>

struct event_data {
    struct coresight_device *sink;
    struct list_head paths;
    struct work_struct free_work;
};

void *setup_aux_event_data(int event_cpu, void **pages, int nr_pages, bool overwrite)
{
    struct event_data *event_data;
    struct coresight_device *sink = NULL;
    struct coresight_path *path;
    int cpu, ret;

    event_data = kzalloc(sizeof(*event_data), GFP_KERNEL);
    if (!event_data)
        return NULL;

    INIT_LIST_HEAD(&event_data->paths);
    INIT_WORK(&event_data->free_work, NULL);

    sink = coresight_get_enabled_sink();
    if (!sink || !sink->alloc_buffer) {
        kfree(event_data);
        return NULL;
    }

    ret = sink->alloc_buffer(sink, pages, nr_pages, overwrite);
    if (ret) {
        kfree(event_data);
        return NULL;
    }

    event_data->sink = sink;

    for_each_possible_cpu(cpu) {
        path = kzalloc(sizeof(*path), GFP_KERNEL);
        if (!path)
            goto fail;

        path->cpu = cpu;
        list_add_tail(&path->node, &event_data->paths);
    }

    return event_data;

fail:
    cancel_work_sync(&event_data->free_work);
    sink->free_buffer(sink);
    kfree(event_data);
    return NULL;
}

